-- Run in Supabase SQL Editor. Enables citizen-only access and admin workflow.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null default 'citizen' check(role in ('citizen','admin')),created_at timestamptz not null default now());
create table if not exists public.service_requests(id uuid primary key default gen_random_uuid(),citizen_id uuid not null references auth.users(id) on delete cascade,category text not null check(category in ('Water supply','Street lighting','Garbage collection','Roads and drainage','Other')),location text not null,description text not null,image_path text,status text not null default 'Pending' check(status in ('Pending','In Progress','Resolved')),admin_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.service_requests enable row level security;
drop policy if exists "Read profiles" on public.profiles; create policy "Read profiles" on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Insert citizen profile" on public.profiles; create policy "Insert citizen profile" on public.profiles for insert to authenticated with check(id=auth.uid() and role='citizen');
drop policy if exists "Update own citizen profile" on public.profiles; create policy "Update own citizen profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role='citizen');
drop policy if exists "Read own requests or all as admin" on public.service_requests; create policy "Read own requests or all as admin" on public.service_requests for select to authenticated using(citizen_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Insert own pending requests" on public.service_requests; create policy "Insert own pending requests" on public.service_requests for insert to authenticated with check(citizen_id=auth.uid() and status='Pending');
drop policy if exists "Admins update requests" on public.service_requests; create policy "Admins update requests" on public.service_requests for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'citizen') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('request-images','request-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
drop policy if exists "Upload own request image" on storage.objects; create policy "Upload own request image" on storage.objects for insert to authenticated with check(bucket_id='request-images' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "Read own request images" on storage.objects; create policy "Read own request images" on storage.objects for select to authenticated using(bucket_id='request-images' and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')));
